import (
	"errors"
	"fmt"
	"strconv"
	"testing"
)

// ErrBadPort is the sentinel error returned by ParsePort when the value is out of range or not numeric.
var ErrBadPort = errors.New("bad port")

// ParsePort parses a port and returns it as an int, wrapping ErrBadPort with %w when out of range or non-numeric.
func ParsePort(s string) (int, error) {
	p, err := strconv.Atoi(s)
	if err != nil {
		return 0, fmt.Errorf("parse %q: %w", s, err)
	}
	if p < 1 || p > 65535 {
		return 0, fmt.Errorf("port %d out of range: %w", p, ErrBadPort)
	}
	return p, nil
}

func TestParsePort(t *testing.T) {
	tests := []struct {
		name, in string
		want     int
		wantErr  bool
	}{
		{"valid", "8080", 8080, false},
		{"out of range", "65536", 0, true},
		{"negative", "-1", 0, true},
		{"non-numeric", "abc", 0, true},
		{"empty", "", 0, true},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := ParsePort(tt.in)
			if (err != nil) != tt.wantErr {
				t.Fatalf("ParsePort(%q) err = %v, wantErr %v", tt.in, err, tt.wantErr)
			}
			if !tt.wantErr && got != tt.want {
				t.Errorf("ParsePort(%q) = %d, want %d", tt.in, got, tt.want)
			}
		})
	}
}

