// SortByLen sorts ss in place by ascending string length (stable).
func SortByLen(ss []string) {
	sort.SliceStable(ss, func(i, j int) bool {
		return len(ss[i]) < len(ss[j])
	})
}

// TestSortByLen tests that SortByLen orders strings by length.
func TestSortByLen(t *testing.T) {
	cases := map[string][]string{
		"empty":         {},
		"single":        []string{"a"},
		"equal length":  []string{"ab", "ab", "ab"},
		"by length":     []string{"a", "ab", "abc", "abcd"},
		"reversed":      []string{"abcd", "abc", "ab", "a"},
		"with spaces":   []string{" ab", " ab ab", "ab", "a"},
		"unicode":       []string{"ab\u0301", "ab", "ab\u0308", "ab\u0303"},
		"unicode order": []string{"ab\u0301", "ab\u0308", "ab\u0303", "ab"},
	}
	for name, want := range cases {
		t.Run(name, func(t *testing.T) {
			got := make([]string, len(want))
			copy(got, want)
			SortByLen(got)
			if !equalSlice(got, want) {
				t.Errorf("SortByLen(%v) = %v, want %v", want, got, want)
			}
		})
	}
}

// equalSlice reports whether a and b contain the same elements in the same order.
func equalSlice(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i, aa := range a {
		if aa != b[i] {
			return false
		}
	}
	return true
}

