import (
	"sync"
)

// Merge fanns-in both inputs into one output and closes it when both inputs are closed.
func Merge(a, b <-chan int) <-chan int {
	out := make(chan int)
	var wg sync.WaitGroup
	wg.Add(2)

	go func() {
		defer wg.Done()
		for n := range a {
			out <- n
		}
	}()

	go func() {
		defer wg.Done()
		for n := range b {
			out <- n
		}
	}()

	go func() {
		wg.Wait()
		close(out)
	}()

	return out
}

