func TestSumHandler(t *testing.T) {
	tests := []struct {
		name, body string
		wantCode   int
		wantJSON   string
	}{
		{"valid", `{"a": 3, "b": 4}`, http.StatusOK, `{"sum": 7}`},
		{"missing a", `{"b": 4}`, http.StatusBadRequest, `{}`},
		{"non-numeric a", `{"a": "three", "b": 4}`, http.StatusBadRequest, `{}`},
		{"empty body", `{}`, http.StatusBadRequest, `{}`},
		{"malformed JSON", `{"a": 3, "b": 4`, http.StatusBadRequest, `{}`},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			rec := httptest.NewRecorder()
			req := httptest.NewRequest(http.MethodPost, "/", []byte(tt.body))
			SumHandler(rec, req)
			res := rec.Result()
			defer res.Body.Close()

			if res.StatusCode != tt.wantCode {
				t.Errorf("status = %d, want %d", res.StatusCode, tt.wantCode)
			}
			if tt.wantJSON != `{}` && res.StatusCode == http.StatusOK {
				want := []byte(tt.wantJSON)
				got := make([]byte, res.ContentLength)
				_, err := res.Body.Read(got)
				if err != nil {
					t.Fatalf("ReadBody: %v", err)
				}
				if !bytes.Equal(got, want) {
					t.Errorf("body = %q, want %q", got, want)
				}
			}
		})
	}
}

