package sandbox

import (
	"container/heap"
)

// IntHeap is a min-heap of ints.
type IntHeap []int

func (h IntHeap) Len() int           { return len(h) }
func (h IntHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h IntHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }

func (h *IntHeap) Push(x interface{}) {
	*h = append(*h, x.(int))
}

func (h *IntHeap) Pop() interface{} {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[0 : n-1]
	return x
}

// PopAllSorted returns all values in ascending order by heapifying and popping.
func PopAllSorted(vals []int) []int {
	h := IntHeap(vals)
	heap.Init(&h)
	out := make([]int, len(vals))
	for i := range out {
		out[i] = heap.Pop(&h).(int)
	}
	return out
}

