				select {
				case <-ctx.Done():
					return
				case ch <- i:
				}
			}
		}()

		done := make(chan struct{})
		go func() {
			defer close(done)
			_ = CountUntil(ctx, ch)
		}()

		cancel() // cancel before the goroutine can send 5
		<-done   // wait for the goroutine to exit
	})

	t.Run("returns count on close", func(t *testing.T) {
		ctx, cancel := context.Background()
		defer cancel()

		ch := make(chan int)
		go func() {
			defer close(ch)
			for i := 0; i < 5; i++ {
				ch <- i
			}
		}()

		count := CountUntil(ctx, ch)
		if count != 5 {
			t.Errorf("CountUntil() = %d, want 5", count)
		}
	})
}

package sandbox

import (
	"bytes"
	"io"
	"testing"
)

func TestReadChunks(t *testing.T) {
	tests := []struct {
		name, data string
		size       int
		wantChunks [][]byte
		wantErr    bool
	}{
		{"chunks fit", "abcde", 2, [][]byte{{'a', 'b'}, {'c', 'd'}, {'e'}}, false},
		{"chunks exactly fit", "ababab", 2, [][]byte{{'a', 'b'}, {'a', 'b'}, {'a', 'b'}}, false},
		{"empty", "", 5, [][]byte(nil), false},
		{"chunk larger than data", "abc", 4, [][]byte{{'a', 'b', 'c'}}, false},
		{"read error", "ab", 2, [][]byte(nil), true},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			r := chunkReader{data: tt.data, err: tt.name == "read error"}
			chunks, err := ReadChunks(&r, tt.size)
			if (err != nil) != tt.wantErr {
				t.Fatalf("ReadChunks(&chunkReader{data: %q, err: %v}, %d) err = %v, wantErr %v", tt.data, tt.err, tt.size, err, tt.wantErr)
			}
			if !tt.wantErr && !equalChunks(chunks, tt.wantChunks) {
				t.Errorf("ReadChunks(&chunkReader{data: %q, err: %v}, %d) = %v, want %v", tt.data, tt.err, tt.size, chunks, tt.wantChunks)
			}
		})
	}
}

type chunkReader struct {
	data string
	err  bool
}

func (r *chunkReader) Read(p []byte) (int, error) {
	if r.err {
		return 0, io.ErrClosed
	}
	n := copy(p, r.data)
	r.data = r.data[n:]
	return n, nil
}

func equalChunks(a, b [][]byte) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if !bytes.Equal(a[i], b[i]) {
			return false
		}
	}
	return true
}
